function update_smultiplot(hObject,plotdata,plotminv,plotmaxv,prfigname,basev,bootflag,pautoflag)
% (C) Maciej Kaminski 2012 (GPLv3 http://www.gnu.org/licenses/gpl-3.0.txt)
if ~ishandle(hObject)
    return
end

%%% MD
set(0,'DefaultFigureVisible',mv.visible_fig);
%%%
handles=guihandles(hObject);
data=guidata(hObject);
data.plotdata=plotdata;
data.plotminv=plotminv;
data.plotmaxv=plotmaxv;
data.prnfilename=prfigname;
guidata(hObject,data);
%amultigraph(handles.axes1,data.plotdata,...
figure(handles.figure1);
if bootflag
    a2multigraph(data.axes1,data.plotdata,...
                   data.plotminv,...
                   data.plotmaxv,...
                   data.plottitl,...
                   data.prnfilename,...
                   data.chanopis,...
                   data.savefigs,...
                   0,...
                   pautoflag,...
                   basev);
else
    amultigraph(data.axes1,data.plotdata,...
                   data.plotminv,...
                   data.plotmaxv,...
                   data.plottitl,...
                   data.prnfilename,...
                   data.chanopis,...
                   data.savefigs,...
                   0,...
                   pautoflag,...
                   basev);
end
set(handles.text1,'String',num2str(plotmaxv));
if data.savefigs
    set(gcf,'PaperPositionMode','auto');
    %set(gcf,'PaperOrientation','landscape');
    set(gcf,'PaperType','A4');
    set(handles.pushbutton1,'Visible','off');
    set(handles.pushbutton2,'Visible','off');
    set(handles.pushbutton3,'Visible','off');
    set(handles.pushbutton4,'Visible','off');
    print(gcf,'-dtiff',[prfigname{1} prfigname{2} '.tif']);
    set(handles.pushbutton1,'Visible','on');
    set(handles.pushbutton2,'Visible','on');
    set(handles.pushbutton3,'Visible','on');
    set(handles.pushbutton4,'Visible','on');
end

